from config.schema_types import BOOL, DATE, INT, MONEY_STRING, TEXT, TIME, UUID, array, choice, nullable, obj, op, parameter, ref

METRIC_KEYS=("principal_disbursed","confirmed_collections","collection_reversals","net_collections","interest_accrued","interest_collected","principal_outstanding","interest_outstanding","contractual_future_interest","overdue_contractual_amount","loss_recorded","closed_with_loss_count","settlement_unknown_count","settlement_confirmed_count","commission_earned","commission_collected","commission_reversed")
STRING_MAP={"type":"object","additionalProperties":TEXT,"description":"Metric-definition text keyed by the named metric, never an unconstrained financial value."}
SCHEMAS={
    "ReportingPeriod":obj({"start":TIME,"end":TIME,"timezone":TEXT,"basis":TEXT}),
    "ReportingMetrics":obj({key:MONEY_STRING for key in METRIC_KEYS}),
    "ReportingActivity":obj({"granularity":choice("day","month"),"points":array(obj({"date":DATE,**{key:MONEY_STRING for key in ("principal_collected","interest_collected","confirmed_collections","collection_reversals","net_collections","collection_count","principal_disbursed","interest_accrued")}})),"repayment_breakdown":obj({key:MONEY_STRING for key in ("principal","interest","other_charges","total")}),"current_annual_rates_bps":array(INT),"definitions":STRING_MAP}),
    "MemberMetrics":obj({"period":ref("ReportingPeriod"),"role":choice("borrower","lender"),"currency":choice("PHP"),"unit":choice("centavos_as_decimal_strings"),"metrics":ref("ReportingMetrics"),"definitions":STRING_MAP,"activity":ref("ReportingActivity"),"comparison":{"nullable":True,"enum":[None],"description":"Currently null; no invented prior-period comparison."},"test_mode":BOOL}),
}
PERIOD=[parameter("start",DATE,"Inclusive Manila date."),parameter("end",DATE,"Exclusive Manila date, at most 366 days after start.")]
OPERATIONS={
    ("MemberMetricsView","GET"):op(ref("MemberMetrics"),summary="Read your scoped financial activity",parameters=[*PERIOD,parameter("role",choice("borrower","lender"))],description="Exact signed decimal strings; future interest is projection, collections are not settlement, count metrics are counts. No prior-period comparison is currently provided."),
    ("OperationsMetricsView","GET"):op(obj({"period":ref("ReportingPeriod"),"currency":choice("PHP"),"unit":TEXT,"metrics":ref("ReportingMetrics"),"definitions":STRING_MAP,"activity":ref("ReportingActivity"),"queues":obj({"open_cases":INT,"verification_pending":INT}),"comparison":{"nullable":True,"enum":[None]},"test_mode":BOOL}),summary="Read finance-only operational metrics",parameters=PERIOD),
    ("ExportView","POST"):op(obj({"id":UUID,"expires_at":TIME,"download_path":TEXT}),obj({"purpose":choice("member_statement","operations_summary"),"role":choice("borrower","lender"),"start":DATE,"end":DATE},[]),status=201,summary="Prepare a purpose-limited statement export",description="Operations summary is finance/admin-only. The actor-bound snapshot expires after ten minutes."),
    ("ExportDownloadView","GET"):op(TEXT,media="text/csv",summary="Download your unexpired statement CSV",description="Actor/role checked again. CSV formula-leading cells are neutralized. 410 when expired; private,no-store."),
    ("CommissionsView","GET"):op(obj({"commissions":array(obj({"id":UUID,"loan_id":UUID,"amount":MONEY_STRING,"collected_amount":MONEY_STRING,"status":TEXT,"policy_version":TEXT,"payer_id":UUID,"created_at":TIME})),"definitions":STRING_MAP,"test_mode":BOOL}),summary="Read finance-only origination commissions"),
    ("ReconciliationView","GET"):op(obj({"operations":array(obj({"id":UUID,"loan_id":nullable(UUID),"kind":TEXT,"status":TEXT,"amount":MONEY_STRING,"payment_id":TEXT,"created_at":TIME})),"inbox":array(obj({"id":UUID,"event_id":TEXT,"state":TEXT,"attempts":INT,"reason":TEXT})),"settlement_notice":TEXT,"test_mode":BOOL}),summary="Read finance-only unresolved payment records",description="At most 100 operations and 100 inbox events. This is a read-only queue; unknown settlement remains unresolved."),
}
